function countSlidingWindow(arr, windowSize) {
    if (arr.length < windowSize) return [];

    const result = [];
    for (let i = 0; i <= arr.length - windowSize; i++) {
        let count = 0;
        for (let j = i; j < i + windowSize; j++) {
            count += arr[j];
        }
        result.push(count);
    }
    return result;
}
